/*
 * Cohort Lens — data loader.
 *
 * Chooses where window.COHORT_LENS_DATA comes from, then starts app.js:
 *   • Live API: open index.html?api=http://localhost:8000 (or set window.COHORT_LENS_API).
 *     Loads the latest completed pipeline run from GET /api/runs/latest/frontend.
 *   • Static: js/data.js, generated by `python -m cohortlens export-frontend`.
 * If the API is unreachable the static export is used and a notice is shown.
 */
(function () {
  'use strict';

  const params = new URLSearchParams(location.search);
  const api = (params.get('api') || window.COHORT_LENS_API || '').replace(/\/$/, '');
  window.COHORT_LENS_API = api || null;

  function fillMasthead(meta) {
    if (!meta) return;
    const set = (id, text) => { const el = document.getElementById(id); if (el && text) el.textContent = text; };
    set('dl-study', `Study ${meta.study}`);
    set('dl-design', meta.design);
    set('dl-indication', meta.indication);
    set('dl-participants', meta.participantsLabel);
    set('dl-cut', `Data cut ${meta.dataCut}`);
    set('dl-ra', `Research associate · ${meta.researchAssociate}`);
    set('dl-source', api ? `Live · ${meta.backend} backend` : `Pipeline export · ${meta.backend} backend`);
  }

  function start(notice) {
    fillMasthead(window.COHORT_LENS_DATA && window.COHORT_LENS_DATA.meta);
    if (notice) window.COHORT_LENS_NOTICE = notice;
    const s = document.createElement('script');
    s.src = 'js/app.js';
    document.body.appendChild(s);
  }

  if (!api) { start(); return; }
  fetch(`${api}/api/runs/latest/frontend`)
    .then(r => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
    .then(d => { window.COHORT_LENS_DATA = d; start(); })
    .catch(err => start(`API ${api} unavailable (${err.message}); showing the bundled pipeline export.`));
})();
